def find_max_pyramid_size(A):
    n = len(A)
    if n == 0:
        return 0

    b = [1] * n
    for i in range(n - 1):
        if A[i] > b[i]:
            b[i + 1] = b[i] + 1
        else:
            b[i + 1] = A[i] + 1

    c = [1] * n
    for i in range(n - 1, 0, -1):
        if A[i] > c[i]:
            c[i - 1] = c[i] + 1
        else:
            c[i - 1] = A[i] + 1

    d = [1] * n
    for i in range(n):
        d[i] = min(b[i], c[i])

    return max(d)
